        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        periods.close(period, total, personTotals, soft);
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total, soft, period.cap());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The periods of each sheet. */
@Repository
public class Periods {

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total, soft, cap FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY from_date", Periods::period, sheetId);
    }

    /** The period of this name on this sheet, or null when there is none. Locks its row for the
     *  rest of the transaction. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND name = ? FOR UPDATE", Periods::period, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The (not soft-) closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period closedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND NOT soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The soft-closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The capped period of the sheet whose dates contain the date, or null when there is none. */
    public Period cappedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND cap IS NOT NULL AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** How many of the person's claims due by in the period are OPEN or PENDING. */
    public int openIn(Period period, long personId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND status IN ('OPEN', 'PENDING') AND due_by >= ? AND due_by <= ?", Integer.class,
                period.sheetId(), personId, Date.valueOf(period.from()), Date.valueOf(period.to()));
        return n == null ? 0 : n;
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, cap) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()), period.cap());
    }

    /** Close (or, when `soft`, soft-close) the period, fixing its due-total and each person's (by
     *  person id) afresh. */
    public void close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals, boolean soft) {
        jdbc.update("UPDATE period SET closed = TRUE, soft = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                soft, total, period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, personTotal));
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ?"
                + " ORDER BY person_id", rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, period.sheetId(), period.name());
        return totals;
    }

    /** Reopen the period: its due-total, and each person's, is live again. */
    public void reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
    }

    private static Period period(ResultSet rs, int i) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getDate("from_date").toLocalDate(),
                rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
                rs.getBoolean("soft"), rs.getObject("cap", Integer.class));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Connection;
import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A sheet as it stood at the end of a date: every change made while the sheet's today was on or
 *  before that date counts, every later change does not, and that date stands in for the sheet's
 *  today. The sheet's rows are rebuilt from the change history (see {@link History}) into the asof
 *  schema, and the work runs against it in place of the live tables, so every rule reads the sheet
 *  as it was. The work must only read: what it writes is thrown away. */
@Service
public class AsOf {

    /** The tables of a sheet's data (keyed by sheet_id) kept in asof_hist and rebuilt into asof. */
    static final List<String> TABLES = List.of("CLAIM", "PERSON", "PERSON_GRADE", "PERSON_HOLD", "PERSON_PATRON",
            "PERSON_WATCH", "PERSON_STATEMENT", "PERIOD", "PERIOD_PERSON_TOTAL", "PERIOD_NUMBER", "RATE", "RATE_VERSION",
            "SHEET_SETTING", "SHEET_SETTING_DATED", "SHEET_ROLE", "SHEET_PERMISSION", "SHEET_DELEGATION",
            "CLAIM_LOG", "SHEET_GRADE_TERMS", "SHEET_HOLIDAY", "SHEET_VOID_REASON", "CLAIM_COMMENT", "PERSON_ALIAS",
            "POOL", "POOL_MEMBER", "PLAN", "PLAN_CLAIM", "CLAIM_LINE", "PERSON_SNAPSHOT");

    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;
    private final Map<String, List<String>> columns = new HashMap<>();

    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager) {
        this.jdbc = jdbc;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    /** Run `work` against the sheet as it stood at the end of `date`. It runs in a transaction of its
     *  own, on one connection, which is rolled back: the rebuilt rows are never kept. */
    public <T> T at(String sheetId, LocalDate date, Supplier<T> work) {
        return transactions.execute(status -> {
            status.setRollbackOnly();
            // One rebuild of the sheet at a time.
            jdbc.query("SELECT id FROM PUBLIC.sheet WHERE id = ? FOR UPDATE", (RowCallbackHandler) rs -> {}, sheetId);
            rebuild(sheetId, date);
            schema("ASOF");
            try {
                return work.get();
            } finally {
                schema("PUBLIC");
            }
        });
    }

    /** What a screen reads: `work` on the sheet as it stood at the end of the as-of date given (see
     *  {@link #at}), or on the live sheet when none is given. Refused: an as-of that is not a date. */
    public <T> T view(String sheetId, String asOfText, Supplier<T> work) throws InvalidSheetRequestException {
        if (asOfText == null || asOfText.isBlank()) return work.get();
        LocalDate date;
        try {
            date = LocalDate.parse(asOfText.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + asOfText);
        }
        return at(sheetId, date, work);
    }

    private void rebuild(String sheetId, LocalDate date) {
        jdbc.update("DELETE FROM ASOF.sheet WHERE id = ?", sheetId);
        jdbc.update("INSERT INTO ASOF.sheet SELECT * FROM PUBLIC.sheet WHERE id = ?", sheetId);
        // Archived only by an archive made by then.
        jdbc.update("UPDATE ASOF.sheet SET today = ?, archived = archived AND (archived_on IS NULL OR archived_on <= ?) "
                + "WHERE id = ?", Date.valueOf(date), Date.valueOf(date), sheetId);
        for (String table : TABLES) {
            List<String> cols = columns(table);
            String names = '"' + String.join("\", \"", cols) + '"';
            // The rows as they stood: each change made by then removes or adds one, in the order made.
            Map<List<Object>, Integer> rows = new LinkedHashMap<>();
            jdbc.query("SELECT " + names + ", H_OP FROM ASOF_HIST.\"" + table + "\" WHERE sheet_id = ? "
                    + "AND (H_MADE_ON IS NULL OR H_MADE_ON <= ?) ORDER BY H_SEQ", (RowCallbackHandler) rs -> {
                        List<Object> row = new ArrayList<>(cols.size());
                        for (int i = 1; i <= cols.size(); i++) row.add(rs.getObject(i));
                        rows.merge(row, "I".equals(rs.getString(cols.size() + 1)) ? 1 : -1, Integer::sum);
                    }, sheetId, Date.valueOf(date));
            // A snapshot of a day is written as the day is left: it is not part of the sheet at the end of it.
            if (table.equals("PERSON_SNAPSHOT")) {
                int leftDay = cols.indexOf("LEFT_DAY");
                rows.keySet().removeIf(row -> {
                    Object left = row.get(leftDay);
                    LocalDate day = left instanceof Date d ? d.toLocalDate() : (LocalDate) left;
                    return !day.isBefore(date);
                });
            }
            jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheetId);
            String insert = "INSERT INTO ASOF.\"" + table + "\" (" + names + ") VALUES ("
                    + "?, ".repeat(cols.size() - 1) + "?)";
            List<Object[]> batch = new ArrayList<>();
            rows.forEach((row, n) -> {
                for (int i = 0; i < n; i++) batch.add(row.toArray());
            });
            if (!batch.isEmpty()) jdbc.batchUpdate(insert, batch);
        }
    }

    private List<String> columns(String table) {
        synchronized (columns) {
            return columns.computeIfAbsent(table, t -> jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
                    + "WHERE TABLE_SCHEMA = 'ASOF' AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION", String.class, t));
        }
    }

    private void schema(String schema) {
        jdbc.execute((ConnectionCallback<Void>) (Connection c) -> {
            c.setSchema(schema);
            return null;
        });
    }
}
