package net.officefloor.hq.app.consolidated;

import java.util.List;
import net.officefloor.hq.app.person.People;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithTree {
    public void respond(@PathVariable("sheetId") String sheetId, People people,
            ObjectResponse<List<String>> response) {
        response.send(people.treeOf(sheetId).stream().sorted().toList());
    }
}
# The ids of the other sheets of the sheet's tree (its ancestors and its descendants, among the
# sheets that exist), by sheet id. Read from the live sheets (a parent is not dated).
respond:
  class: net.officefloor.hq.app.consolidated.RespondWithTree
  govern: [ readonly-transaction ]
# The ids of the sheet's descendants: its children (the sheets naming it as their parent), theirs,
# and so on, nearest first. Read from the live sheets (a parent is not dated).
respond:
  class: net.officefloor.hq.app.consolidated.RespondWithDescendants
  govern: [ readonly-transaction ]
import { useCallback, useEffect, useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { LiveReads } from '../asof/useAsOf';
import { useClaims } from '../claims/useClaims';
import { useSheetTotals } from '../claims/useSheetTotals';
import { usePeople } from '../people/usePeople';
import { hundredths, totalDue, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheet } from '../sheet/useSheet';
import { useDescendants } from './useDescendants';

type Figures = { people: number; due: string; overdue: string };

const same = (a: Figures | null, b: Figures | null) =>
  a === b || (a !== null && b !== null && a.people === b.people && a.due === b.due && a.overdue === b.overdue);

/** One sheet's figures as that sheet shows them (its header's people count, due-total and
 *  overdue-total), reported once everything they are worked out from has loaded. Renders nothing. */
function SheetFigures({ sheet, report }: { sheet: string; report: (sheet: string, figures: Figures | null) => void }) {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const settings = useSettings(sheet);
  const today = useSheet(sheet);
  const { dueTotal, overdueTotal } = useSheetTotals(sheet);
  const ready = people.isSuccess && claims.isSuccess && rates.isSuccess && settings.isSuccess && today.isSuccess;
  const count = people.data?.length ?? 0;
  useEffect(() => {
    report(sheet, ready ? { people: count, due: dueTotal, overdue: overdueTotal } : null);
  }, [sheet, ready, count, dueTotal, overdueTotal, report]);
  useEffect(() => () => report(sheet, null), [sheet, report]);
  return null;
}

/**
 * The consolidated figures over the sheet and all its descendants (see useDescendants): how many
 * people, and each sheet's due-total and overdue-total as that sheet shows them, added up — always
 * as the sheets stand now, even while the screen shows the sheet as of a date. A sheet
 * with no children shows its own. Blank until every sheet's figures have loaded.
 */
function Consolidated({ sheet }: { user: string; sheet: string }) {
  const { data: descendants } = useDescendants(sheet);
  const sheets = descendants === undefined ? [] : [sheet, ...descendants];
  const [figures, setFigures] = useState<Record<string, Figures | null>>({});
  const report = useCallback((id: string, f: Figures | null) => {
    setFigures((was) => (same(was[id] ?? null, f) ? was : { ...was, [id]: f }));
  }, []);
  const all = sheets.map((id) => figures[id] ?? null);
  const ready = sheets.length > 0 && all.every((f) => f !== null);
  const loaded = all.filter((f): f is Figures => f !== null);
  return (
    <section data-testid="consolidated">
      <LiveReads value={true}>
        {sheets.map((id) => (
          <SheetFigures key={id} sheet={id} report={report} />
        ))}
      </LiveReads>
      <p>
        Consolidated: people <strong data-testid="consolidated-people-count">{ready ? loaded.reduce((n, f) => n + f.people, 0) : ''}</strong>
        , due <strong data-testid="consolidated-due-total">{ready ? totalDue(loaded.map((f) => hundredths(f.due))) : ''}</strong>
        , overdue <strong data-testid="consolidated-overdue-total">{ready ? totalDue(loaded.map((f) => hundredths(f.overdue))) : ''}</strong>
      </p>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 21, Component: Consolidated });
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims } from '../claims/useClaims';
import { type Person } from '../people/usePeople';
import { showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { personPeriodCarriedCents, personPeriodDueCents, usePeriods } from './usePeriods';

/** One header per period on the sheet. */
function PeriodColumns({ sheet }: { user: string; sheet: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name}</th>
      ))}
    </>
  );
}

/**
 * A person's due-total for every period on the sheet: the due of their claims dated in it that were
 * counted at the end of its last day (by their status log),
 * or, once the period is closed, the figure fixed then (0.00 for a person added since); and beside it
 * what they carried into it: the due of their counted claims belonging to an earlier period that were
 * still OPEN or PENDING at the end of this one.
 */
function PersonPeriods({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const today = useSheetToday(sheet);
  return (
    <>
      {periods.map((p) => (
        <td key={p.name}>
          <span data-testid={`person-period-${p.name}-due-total`}>
            {showDue(personPeriodDueCents(p, person, claims, rates, floor, late, today))}
          </span>{' '}
          (carried{' '}
          <span data-testid={`person-period-${p.name}-carried`}>
            {showDue(personPeriodCarriedCents(p, periods, person, claims, rates, floor, late, today))}
          </span>
          )
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 15, Component: PeriodColumns }),
  PersonCells.fill({ order: 15, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { claimDueCents, type Claim, type ClaimStatus, type Late } from '../claims/useClaims';
import { gradeOn, heldOn, type Person } from '../people/usePeople';
import { hundredths, claimRateOn, totalDue, type Rate } from '../rates/useRates';
import type { FloorOn } from '../settings/useSettings';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** A period as the server sends it: its name, its from and to dates (yyyy-mm-dd), inclusive, whether
 *  it is closed and, when it is, the due-total fixed when it was closed and each person's (by person
 *  id; a person not in it, added since, has 0.00), and whether it is only soft-closed: its figures
 *  are fixed as by a close, but claims dated in it can still be changed; and its cap on each person's
 *  OPEN or PENDING claims due by in it (null for none). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  closedPersonTotals: Record<string, string>;
  soft: boolean;
  cap: number | null;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date, re-read whenever the sheet is loaded. */
export function usePeriods(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(periodsKey(sheet), asOf),
    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The fiscal year a date (yyyy-mm-dd) falls in, FY<yyyy>: a fiscal year starts on the first day of
 *  the sheet's fiscal start month (1 to 12) and is named by the calendar year that day falls in. */
export function fiscalYear(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** A fiscal year the server accepts: yyyy. */
export const YEAR = /^\d{4}$/;

/** A period cap the server accepts: a whole number of at least 1. */
export const CAP = /^[1-9]\d{0,8}$/;

/** A date the server accepts: yyyy-mm-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain `date` (yyyy-mm-dd), or undefined when none does. Periods never
 *  overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** The status a claim had at the end of `date` (yyyy-mm-dd), as its status log records it: the last
 *  line dated on or before it; null when the claim was added after it. A claim kept before the log
 *  began (no lines) goes by its status now. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a person's claim counts in a period's due-total: due by in it (its due-by as fixed when it was added), and counted (OPEN, PENDING
 *  or SETTLED) by the status it had at the end of the period's last day — not a deferred one, nor
 *  one open then and dated within the person's hold (or the person's once the sheet's today reaches
 *  their retirement date), unless a statement binds it. */
function countsIn(period: Period, person: Person, claim: Claim, today: string, now: boolean): boolean {
  if (claim.personId !== person.id || periodOf([period], claim.dueBy) === undefined || claim.deferred) return false;
  return countedAs(person, claim, now ? claim.status : statusAt(claim, period.to), today);
}

/** Whether a person's claim, with `status`, is counted: OPEN, PENDING or SETTLED, and not one open
 *  and dated within the person's hold (or retirement), unless a statement binds it. */
function countedAs(person: Person, claim: Claim, status: ClaimStatus | null, today: string): boolean {
  if (status !== 'OPEN' && status !== 'PENDING' && status !== 'SETTLED') return false;
  if (status === 'SETTLED' || !heldOn(person, claim.date, today)) return true;
  return claim.stated && status !== 'PENDING';
}

/** A person's due-total for a period, in cents: the one fixed when the period was closed (0 for a
 *  person added since), else the dues, as shown now, of their claims that count in it (see
 *  `countsIn`: by the status each had at the period's end, or with `now` by its status now), n/a
 *  ones skipped. */
export function personPeriodDueCents(period: Period, person: Person, claims: Claim[], rates: Rate[], floor: FloorOn, late: Late, today: string, now = false): bigint {
  if (period.closed) {
    const fixed = period.closedPersonTotals?.[String(person.id)];
    return fixed === undefined ? 0n : hundredths(fixed);
  }
  return claims
    .filter((c) => countsIn(period, person, c, today, now))
    .reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, claimRateOn(rates, gradeOn(person, c.date), c), late) ?? 0n), 0n);
}

/** A person's carried figure for a period, in cents: the dues, as shown now, of their claims that
 *  count (as in `countsIn`) which belong, by due-by, to a period ending before this one starts and
 *  were still OPEN or PENDING at the end of this period's last day (by their status log). */
export function personPeriodCarriedCents(period: Period, periods: Period[], person: Person, claims: Claim[], rates: Rate[], floor: FloorOn, late: Late, today: string): bigint {
  return claims
    .filter((c) => {
      const home = periodOf(periods, c.dueBy);
      if (c.personId !== person.id || c.deferred || home === undefined || home.to >= period.from) return false;
      const status = statusAt(c, period.to);
      return (status === 'OPEN' || status === 'PENDING') && countedAs(person, c, status, today);
    })
    .reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, claimRateOn(rates, gradeOn(person, c.date), c), late) ?? 0n), 0n);
}

/** A period's due-total: everyone's due-total for it added up (with `now`, each claim counted by its
 *  status now rather than at the period's end). */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: FloorOn, late: Late, today: string, now = false): string {
  return totalDue(people.map((p) => personPeriodDueCents(period, p, claims, rates, floor, late, today, now)));
}

